// Exotel sends application/x-www-form-urlencoded.
// n8n auto-parses it into json if content-type is set correctly.
// Relevant fields: CallSid, From, To, Status, Direction, StartTime, EndTime
const body = $input.first().json.body || $input.first().json;

const status    = (body.Status || body.CallStatus || '').toLowerCase();
const from      = body.From    || body.CallFrom || '';
const to        = body.To      || body.CallTo   || '';
const callSid   = body.CallSid || body.Sid      || '';
const startTime = body.StartTime ? new Date(body.StartTime).toISOString() : new Date().toISOString();

// Only process missed / no-answer calls
const isMissed = ['no-answer', 'busy', 'failed', 'missed'].includes(status);

if (!isMissed) {
  return [{ json: { skip: true, status, callSid } }];
}

// Normalise phone to E.164 (Exotel may send with leading 0 or +91)
const normalisePhone = (raw) => {
  const digits = raw.replace(/[^0-9]/g, '');
  if (digits.startsWith('91') && digits.length === 12) return digits;
  if (digits.length === 10) return `91${digits}`;
  return digits;
};

return [{
  json: {
    skip:         false,
    call_sid:     callSid,
    caller_raw:   from,
    caller_phone: normalisePhone(from),
    called_phone: normalisePhone(to),
    status,
    started_at:   startTime,
  }
}];

const missed   = $('Parse Exotel Payload').first().json;
const employee = $input.first().json || {};

const callerName  = employee?.name || 'there';
const calledAt    = new Date(missed.started_at).toLocaleTimeString('en-IN', {
  hour: '2-digit', minute: '2-digit', timeZone: 'Asia/Kolkata'
});

const waMessage = `Hi ${callerName} 👋\n\nWe noticed you called us at *${calledAt}* but we couldn't connect.\n\nA team member will call you back shortly. If it's urgent, reply to this message and we'll prioritise your query.\n\n— Team`;

return [{
  json: {
    ...missed,
    caller_name:   callerName,
    employee_id:   employee?.id         || null,
    department:    employee?.department  || null,
    whatsapp_msg:  waMessage,
  }
}];
